package com.ecommerce.commerceapi.inventory.api; import com.ecommerce.commerceapi.inventory.service.InventoryService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/inventory") public class InventoryController{private final InventoryService service;public InventoryController(InventoryService s){service=s;}@GetMapping("/{variantId}") public java.util.Map<String,Integer> balance(@PathVariable Long variantId){return java.util.Map.of("currentStock",service.balance(variantId));}@PostMapping("/transactions") @ResponseStatus(HttpStatus.CREATED) public void record(@Valid @RequestBody InventoryTransactionRequest request){service.record(request);}}
